from itertools import permutations
# use backtracking
n=27
size=2*n
seq=[0]*size
used=[0]*(n+1)

def backtrack(pos):
    if pos==size:
        return True
    if seq[pos]!=0:
        return backtrack(pos+1)
    for v in range(n,0,-1):
        if used[v]==0:
            j=pos+v+1
            if j<size and seq[j]==0:
                seq[pos]=seq[j]=v
                used[v]=1
                if backtrack(pos+1):
                    return True
                seq[pos]=seq[j]=0
                used[v]=0
    return False

if backtrack(0):
    print(seq)
